;(function(){
/* =====================================================================
   theme.js — Bascule clair / sombre, persistance localStorage.
   Conforme RGAA : aucun visuel dépendant uniquement de JS.
   Pré-applique data-theme avant le rendu via script inline (voir base.html).
   ===================================================================== */
(function () {
  "use strict";

  var STORAGE_KEY = "bddpe-theme";

  function getStoredTheme() {
    try { return localStorage.getItem(STORAGE_KEY); }
    catch (e) { return null; }
  }

  function storeTheme(theme) {
    try { localStorage.setItem(STORAGE_KEY, theme); }
    catch (e) { /* mode privée : on ignore */ }
  }

  function systemTheme() {
    return window.matchMedia &&
           window.matchMedia("(prefers-color-scheme: dark)").matches
           ? "dark" : "light";
  }

  function currentTheme() {
    return document.documentElement.getAttribute("data-theme") || systemTheme();
  }

  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    syncToggleButtons(theme);
  }

  function syncToggleButtons(theme) {
    var buttons = document.querySelectorAll("[data-theme-toggle]");
    for (var i = 0; i < buttons.length; i++) {
      var btn = buttons[i];
      var pressed = (theme === "dark");
      btn.setAttribute("aria-pressed", pressed ? "true" : "false");
      btn.setAttribute("aria-label",
        pressed ? "Activer le thème clair" : "Activer le thème sombre");
      btn.setAttribute("title",
        pressed ? "Thème sombre actif — basculer vers le thème clair"
                : "Thème clair actif — basculer vers le thème sombre");
    }
  }

  function toggleTheme() {
    var next = currentTheme() === "dark" ? "light" : "dark";
    applyTheme(next);
    storeTheme(next);
  }

  // Suivi des préférences système si l'utilisateur n'a rien forcé.
  function bindSystemListener() {
    if (!window.matchMedia) return;
    var mq = window.matchMedia("(prefers-color-scheme: dark)");
    var handler = function () {
      if (!getStoredTheme()) { applyTheme(systemTheme()); }
    };
    if (mq.addEventListener) mq.addEventListener("change", handler);
    else if (mq.addListener) mq.addListener(handler);
  }

  // Branchement des boutons toggle.
  function bindToggles() {
    var buttons = document.querySelectorAll("[data-theme-toggle]");
    for (var i = 0; i < buttons.length; i++) {
      buttons[i].addEventListener("click", toggleTheme);
    }
  }

  function init() {
    syncToggleButtons(currentTheme());
    bindToggles();
    bindSystemListener();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }
})();
})();
;(function(){
/* =====================================================================
   nav.js — Gestion accessible des menus mobiles (header + sidebar).
   Pattern : aria-expanded + aria-controls, fermeture Escape, click
   extérieur, focus trap optionnel, SOAP baseline.
   ===================================================================== */
(function () {
  "use strict";

  function isOpen(el) {
    return el && el.getAttribute("data-open") === "true";
  }
  function setOpen(el, open) {
    if (!el) return;
    el.setAttribute("data-open", open ? "true" : "false");
  }
  function setExpanded(el, expanded) {
    if (!el) return;
    el.setAttribute("aria-expanded", expanded ? "true" : "false");
  }

  /* /////
     Menu mobile du header public (.nav-toggle + .primary-nav + .menu-overlay)
  ///// */
  function setupHeaderNav() {
    var toggle = document.querySelector(".nav-toggle[data-controls='primary-nav']");
    var nav = document.getElementById("primary-nav");
    var overlay = document.querySelector(".menu-overlay");
    if (!toggle || !nav) return;

    var lastFocus = null;

    function open() {
      lastFocus = document.activeElement;
      setOpen(nav, true);
      setExpanded(toggle, true);
      if (overlay) setOpen(overlay, true);
      document.body.style.overflow = "hidden";
      // Met le focus sur le premier lien
      var firstLink = nav.querySelector("a, button");
      if (firstLink) firstLink.focus();
    }
    function close() {
      setOpen(nav, false);
      setExpanded(toggle, false);
      if (overlay) setOpen(overlay, false);
      document.body.style.overflow = "";
      if (lastFocus && typeof lastFocus.focus === "function") {
        lastFocus.focus();
      }
    }
    function toggle() { isOpen(nav) ? close() : open(); }

    toggle.addEventListener("click", toggle);
    if (overlay) overlay.addEventListener("click", close);

    nav.addEventListener("click", function (e) {
      // Ferme sur clic d'un lien de la nav (UX mobile).
      if (e.target.matches("a") && e.target.getAttribute("href") !== "#") {
        // Conserve la navigation : ferme simplement l'overlay.
        var wasOpen = isOpen(nav);
        if (wasOpen) close();
      }
    });

    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && isOpen(nav)) {
        close();
        toggle.focus();
      }
    });

    // Reset sur passage desktop.
    var mq = window.matchMedia("(min-width: 880px)");
    function resetOnDesktop() {
      if (mq.matches && isOpen(nav)) close();
    }
    if (mq.addEventListener) mq.addEventListener("change", resetOnDesktop);
    else if (mq.addListener) mq.addListener(resetOnDesktop);
  }

  /* /////
     Sidebar dashboard (.sidebar-toggle + .sidebar + .sidebar-overlay)
  ///// */
  function setupSidebar() {
    var toggle = document.querySelector(".sidebar-toggle");
    var sidebar = document.querySelector(".sidebar");
    var overlay = document.querySelector(".sidebar-overlay");
    if (!toggle || !sidebar) return;

    var lastFocus = null;

    function open() {
      lastFocus = document.activeElement;
      setOpen(sidebar, true);
      setExpanded(toggle, true);
      if (overlay) setOpen(overlay, true);
      document.body.style.overflow = "hidden";
      var firstLink = sidebar.querySelector("a, button");
      if (firstLink) firstLink.focus();
    }
    function close() {
      setOpen(sidebar, false);
      setExpanded(toggle, false);
      if (overlay) setOpen(overlay, false);
      document.body.style.overflow = "";
      if (lastFocus && typeof lastFocus.focus === "function") {
        lastFocus.focus();
      }
    }
    function toggleFn() { isOpen(sidebar) ? close() : open(); }

    toggle.addEventListener("click", toggleFn);
    if (overlay) overlay.addEventListener("click", close);

    sidebar.addEventListener("click", function (e) {
      if (e.target.matches("a") && e.target.getAttribute("href") !== "#") {
        if (isOpen(sidebar)) close();
      }
    });

    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && isOpen(sidebar)) {
        close();
        toggle.focus();
      }
    });

    var mq = window.matchMedia("(min-width: 880px)");
    function resetOnDesktop() {
      if (mq.matches && isOpen(sidebar)) close();
    }
    if (mq.addEventListener) mq.addEventListener("change", resetOnDesktop);
    else if (mq.addListener) mq.addListener(resetOnDesktop);
  }

  /* /////
     Toggle des filtres (panel collapsible mobile)
  ///// */
  function setupFiltersToggle() {
    var toggle = document.querySelector(".filters-toggle");
    var panel = document.querySelector(".filters");
    if (!toggle || !panel) return;
    toggle.addEventListener("click", function () {
      var open = panel.getAttribute("data-open") === "true";
      panel.setAttribute("data-open", open ? "false" : "true");
      toggle.setAttribute("aria-expanded", open ? "false" : "true");
    });
    var mq = window.matchMedia("(min-width: 1024px)");
    function reset() {
      if (mq.matches) {
        panel.setAttribute("data-open", "true");
        toggle.setAttribute("aria-hidden", "true");
      } else {
        panel.setAttribute("data-open", "false");
        toggle.setAttribute("aria-expanded", "false");
        toggle.removeAttribute("aria-hidden");
      }
    }
    if (mq.addEventListener) mq.addEventListener("change", reset);
    else if (mq.addListener) mq.addListener(reset);
    reset();
  }

  /* /////
     Toggle carte (vue map/list sur les structures)
  ///// */
  function setupMapToggle() {
    var toggle = document.querySelector(".map-toggle");
    var wrap = document.querySelector(".map-wrapper");
    if (!toggle || !wrap) return;
    if (window.matchMedia && window.matchMedia("(min-width: 1100px)").matches) return;
    toggle.addEventListener("click", function () {
      var open = wrap.getAttribute("data-open") === "true";
      wrap.setAttribute("data-open", open ? "false" : "true");
      toggle.setAttribute("aria-expanded", open ? "false" : "true");
    });
  }

  function init() {
    setupHeaderNav();
    setupSidebar();
    setupFiltersToggle();
    setupMapToggle();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }
})();

})();
;(function(){
/* =====================================================================
   filters.js — Persistance des filtres de la liste de structures.
   Conserve les filtres dans localStorage (simples), restaure au chargement.
   Conforme RGAA : dégradation gracieuse, pas de dépendance JS pour naviguer.
   ===================================================================== */
(function () {
  "use strict";

  var STORAGE_KEY = "bddpe-filters-structures";

  function getForm() {
    return document.querySelector("form[data-filters-form]");
  }

  function readQuery() {
    var qs = window.location.search.replace(/^\?/, "");
    var out = {};
    if (!qs) return out;
    qs.split("&").forEach(function (pair) {
      if (!pair) return;
      var idx = pair.indexOf("=");
      var k = decodeURIComponent(idx === -1 ? pair : pair.slice(0, idx));
      var v = decodeURIComponent(idx === -1 ? "" : pair.slice(idx + 1));
      if (k && k !== "page") out[k] = v;
    });
    return out;
  }

  function storeFromUrl() {
    var q = readQuery();
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(q)); }
    catch (e) {}
  }

  function applyStoredOnReset() {
    var form = getForm();
    if (!form) return;
    var resetBtn = form.querySelector("[data-reset-filters]");
    if (!resetBtn) return;
    resetBtn.addEventListener("click", function () {
      try { localStorage.removeItem(STORAGE_KEY); } catch (e) {}
    });
  }

  function init() {
    // Si la liste contient des filtres actifs venant de l'URL, on stocke.
    var q = readQuery();
    if (Object.keys(q).length > 0) {
      storeFromUrl();
    }
    applyStoredOnReset();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }
})();
})();
;(function(){
/* =====================================================================
   password.js — Bascule de visibilité des champs mot de passe.
   Conforme RGAA : aria-pressed sur bouton, état reflété sur l'input
   (type password/text) ET sur la label accessible.
   ===================================================================== */
(function () {
  "use strict";

  function setupToggle(btn) {
    var group = btn.parentElement;
    var input = group ? group.querySelector("input") : null;
    if (!input || !btn) return;

    var icons = btn.querySelectorAll("svg");
    var iconOn = icons.length > 0 ? icons[0] : null;
    var iconOff = icons.length > 1 ? icons[1] : null;
    var labelOn = btn.getAttribute("data-label-show") || "Afficher le mot de passe";
    var labelOff = btn.getAttribute("data-label-hide") || "Masquer le mot de passe";

    btn.setAttribute("aria-pressed", "false");
    btn.setAttribute("aria-label", labelOn);

    btn.addEventListener("click", function () {
      var reveal = btn.getAttribute("aria-pressed") !== "true";
      input.type = reveal ? "text" : "password";
      btn.setAttribute("aria-pressed", reveal ? "true" : "false");
      btn.setAttribute("aria-label", reveal ? labelOff : labelOn);
      if (iconOn && iconOff) {
        iconOn.classList.toggle("hidden", reveal);
        iconOff.classList.toggle("hidden", !reveal);
      }
      // Replacer le curseur dans le champ pour reprendre immédiatement la saisie.
      try { var len = input.value.length; input.focus(); input.setSelectionRange(len, len); } catch (e) {}
    });
  }

  function init() {
    var buttons = document.querySelectorAll("[data-password-toggle]");
    for (var i = 0; i < buttons.length; i++) setupToggle(buttons[i]);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }
})();

})();